package com.fasterxml.jackson.dataformat.xml;

import com.fasterxml.jackson.annotation.JsonRawValue;
import com.fasterxml.jackson.dataformat.xml.annotation.JacksonXmlProperty;
import com.fasterxml.jackson.dataformat.xml.annotation.JacksonXmlRootElement;
import com.fasterxml.jackson.dataformat.xml.annotation.JacksonXmlText;
import com.fasterxml.jackson.dataformat.xml.XmlMapper;
import org.junit.Test;
import static org.junit.Assert.*;

public class ToXmlGeneratorRawValueUnwrappedTest {
    @JacksonXmlRootElement(localName = "test-pojo")
    public static class TestPojo {
        @JacksonXmlProperty(isAttribute = true)
        public String id;

        @JacksonXmlText
        @JsonRawValue
        public String value;
    }

    @Test
    public void testRawValueWithJacksonXmlText() throws Exception {
        XmlMapper mapper = new XmlMapper();
        TestPojo pojo = new TestPojo();
        pojo.id = "123";
        pojo.value = "<a>A</a><b someAttribute=\"B\">B</b>";

        String xml = mapper.writeValueAsString(pojo);
        // Expected: <test-pojo id="123"><a>A</a><b someAttribute="B">B</b></test-pojo>
        // We'll check that there's no <value> element and that the raw XML is inserted directly.
        assertTrue("Should not contain '<value>'", !xml.contains("<value>"));
        assertTrue("Should contain raw XML", xml.contains("<a>A</a><b someAttribute=\"B\">B</b>"));
        assertTrue("Should have id attribute", xml.contains("id=\"123\""));
        // Also verify the structure is correct by checking the root element
        assertTrue(xml.startsWith("<test-pojo"));
        // The raw XML should be inside the root element, not wrapped.
        // We can do a more precise check by parsing and verifying, but for simplicity:
        // Remove the root start and end tags and see what's left.
        String inner = xml.replaceFirst("<test-pojo[^>]*>", "").replaceFirst("</test-pojo>", "");
        // inner should be exactly the raw XML (maybe with whitespace?).
        // The generator may add newlines, so trim.
        assertEquals("<a>A</a><b someAttribute=\"B\">B</b>", inner.trim());
    }
}

